import dotenv from 'dotenv';
import express from 'express';
import cors from 'cors';
import bodyParser from 'body-parser';
import nodemailer from 'nodemailer';
import { claimIp, releaseIp } from './_seenIp.js';

dotenv.config();

console.log('Environment variables loaded:');
console.log('GMAIL_USER:', process.env.GMAIL_USER ? 'SET' : 'NOT SET');
console.log('GMAIL_APP_PASSWORD:', process.env.GMAIL_APP_PASSWORD ? 'SET' : 'NOT SET');

/* -------------------------------------------------------------------------- */
/*  Visitor notification email – Portfolio design system                      */
/*  Table-based layout + inline styles so it renders well in Gmail & others.  */
/*  Matches the portfolio's glass morphism design                            */
/* -------------------------------------------------------------------------- */

const TIME_ZONE = process.env.EMAIL_TIMEZONE || 'Asia/Manila';

const C = {
  // Light theme colors (matching portfolio)
  page: '#F4F4ED',
  cardStart: 'rgba(255, 255, 255, 0.97)',
  cardEnd: 'rgba(186, 209, 255, 0.96)',
  cardMid1: 'rgba(255, 255, 255, 0.93)',
  cardMid2: 'rgba(219, 231, 255, 0.95)',
  tile: '#F8FAFC',
  border: '#E2E8F0',
  text: '#0F172A',
  muted: '#64748B',
  navy: '#0C1226',
  cream: '#F4F4ED',
  orange: '#FF7A1A',
  orangeInk: '#C95C00',
  shadow: 'rgba(6, 12, 26, 0.5)',
};

const FONT = `'Segoe UI',-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif`;
const MONO = `'SF Mono',Consolas,Menlo,monospace`;

// Escape user-supplied values before putting them in HTML
const esc = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

const joinParts = (parts, sep = ' ') => parts.filter(Boolean).map(esc).join(sep);

// Icons are embedded PNGs (Gmail strips inline <svg>). Only icons actually used in an email get attached,
// so no unused icon shows up as an attachment chip.
const ICON_DATA = {
  desktop: '',
  eyes: '',
  globe: '',
  heart: '',
  mobile: '',
  os: '',
  pin: '',
  tablet: '',
};
const ICON_ATTACHMENTS = Object.entries(ICON_DATA).map(([name, b64]) => ({
  filename: `${name}.png`,
  content: Buffer.from(b64, 'base64'),
  contentType: 'image/png',
  cid: `icon-${name}@portfolio`,
  contentDisposition: 'inline',
}));
const iconImg = (name, size, style = '') =>
  `<img src="cid:icon-${name}@portfolio" width="${size}" height="${size}" alt="" style="display:inline-block;border:0;${style}">`;

const ICON_GLOBE = (size = 46) => iconImg('globe', size, 'display:block;');
const ICON_EYES = (size = 30) => iconImg('eyes', size, 'vertical-align:-5px;');
const ICON_HEART = (size = 14) => iconImg('heart', size, 'vertical-align:-2px;');

// 2-letter country code -> flag image (falls back to a globe icon)
const flagFor = (code) => {
  const c = String(code || '').toLowerCase();
  if (!/^[a-z]{2}$/.test(c)) return ICON_GLOBE();
  return `<img src="https://flagcdn.com/w80/${c}.png" width="46" alt="${c.toUpperCase()}" style="display:block;border-radius:6px;border:1px solid #d9dcf0;">`;
};

const deviceIcon = (type) => {
  const t = String(type || '').toLowerCase();
  if (t.includes('mobile') || t.includes('phone')) return iconImg('mobile', 20);
  if (t.includes('tablet')) return iconImg('tablet', 20);
  return iconImg('desktop', 20);
};

const label = (text, color = C.orangeInk) =>
  `<div style="font-size:10px;letter-spacing:2.2px;text-transform:uppercase;color:${color};font-weight:700;">${text}</div>`;

const spacer = (h) =>
  `<div style="height:${h}px;line-height:${h}px;font-size:0;">&nbsp;</div>`;

// Pill badge
const pill = (icon, text, tint, textColor) => `
  <td style="padding:0 8px 8px 0;">
    <table role="presentation" cellpadding="0" cellspacing="0" border="0">
      <tr>
        <td style="background:${tint};border:1px solid ${C.border};border-radius:999px;padding:9px 16px;
          font-size:13px;font-weight:600;color:#0C1226;white-space:nowrap;">${icon}&nbsp; ${text}</td>
      </tr>
    </table>
  </td>`;

// Info card with a coloured top edge
const card = (icon, title, value, accent, mono = false) => `
  <td width="50%" valign="top" style="padding:6px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
      style="background:${C.tile};border:1px solid ${C.border};border-radius:18px;overflow:hidden;">
      <tr><td height="3" style="height:3px;line-height:3px;font-size:0;background:${accent};">&nbsp;</td></tr>
      <tr>
        <td style="padding:18px;">
          <div style="font-size:22px;line-height:1;color:#0C1226;">${icon}</div>
          ${spacer(12)}
          ${label(title)}
          <div style="font-size:${mono ? 14 : 16}px;color:#0C1226;font-weight:700;margin-top:6px;line-height:1.4;
            ${mono ? `font-family:${MONO};` : ''}word-break:break-all;">${value}</div>
        </td>
      </tr>
    </table>
  </td>`;

const buildEmailHtml = (v = {}) => {
  const loc = v.location || {};
  const flag = flagFor(loc.countryCode || loc.country_code);
  const cityLine = esc(loc.city || loc.country || 'Somewhere on Earth');
  const subLocation = joinParts([loc.region, loc.country], ', ');


  const deviceName = joinParts([v.device?.vendor, v.device?.model]) || esc(v.device?.type || 'Desktop');
  const osText = joinParts([v.os?.name || 'Unknown', v.os?.version]);
  const browserText = joinParts([v.browser?.name || 'Unknown', v.browser?.version]);

  const parsed = v.timestamp ? new Date(v.timestamp) : new Date();
  const visit = isNaN(parsed.getTime()) ? new Date() : parsed;
  const visitDate = visit.toLocaleDateString('en-US', {
    weekday: 'long', month: 'long', day: 'numeric', year: 'numeric', timeZone: TIME_ZONE,
  });
  const visitClock = visit.toLocaleTimeString('en-US', {
    hour: 'numeric', minute: '2-digit', timeZone: TIME_ZONE,
  });

  const shortUrl = (value, max = 70) => {
    const str = String(value || '').trim();
    if (!str) return '';
    let out = str;
    try {
      const u = new URL(str);
      out = u.pathname + u.search;
      if (out === '/') out = '/ (home)';
    } catch (_) { /* not a full URL - show as given */ }
    return out.length > max ? out.slice(0, max - 1) + '…' : out;
  };

  const refText = (() => {
    if (typeof v.referrer !== 'string') return '';
    if (!v.referrer.trim()) return 'Direct visit (typed link, bookmark or app)';
    try { return new URL(v.referrer).hostname.replace(/^www\./, ''); } catch (_) { return v.referrer.slice(0, 70); }
  })();
  const pageText = shortUrl(v.page || v.pathname || v.url);
  const langText = String(v.language || '').split(',')[0].trim();

  const infoRow = (k, val) => `
    <tr>
      <td valign="top" style="padding:4px 16px 4px 0;font-size:12px;color:${C.muted};white-space:nowrap;">${k}</td>
      <td valign="top" style="padding:4px 0;font-size:13px;font-weight:600;color:${C.navy};word-break:break-word;">${esc(val)}</td>
    </tr>`;

  const infoRows = [
    refText && infoRow('Came from', refText),
    pageText && infoRow('Viewed page', pageText),
    langText && infoRow('Language', langText),
  ].filter(Boolean).join('');

  const visitInfo = infoRows
    ? `${spacer(18)}
       ${label('Visit details', C.orangeInk)}
       ${spacer(6)}
       <table role="presentation" cellpadding="0" cellspacing="0" border="0">${infoRows}</table>`
    : '';

  const preheader = `${cityLine}${subLocation ? ', ' + subLocation : ''} · ${esc(visitClock)}`;

  return `<!DOCTYPE html>
<html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
  </head>
  <body style="margin:0;padding:0;background:${C.page};font-family:${FONT};">
    <div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent;">${preheader}</div>

    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${C.page}"
      style="background:${C.page};">
      <tr>
        <td align="center" style="padding:44px 12px;">

          <table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0"
            style="max-width:600px;width:100%;background:linear-gradient(100deg,${C.cardStart} 0%,${C.cardMid1} 42%,${C.cardMid2} 76%,${C.cardEnd} 100%);
            border:1px solid ${C.border};border-radius:24px;overflow:hidden;
            box-shadow:inset 0 0 0 1px ${C.border},inset 0 1px 0 rgba(255,255,255,0.5),0 30px 70px -40px ${C.shadow};">

            <!-- Hero -->
            <tr>
              <td align="left" style="padding:40px 36px 36px 36px;">
                <table role="presentation" cellpadding="0" cellspacing="0" border="0">
                  <tr>
                    <td style="background:${C.orange};border-radius:999px;padding:8px 16px;
                      font-size:10px;letter-spacing:2.2px;text-transform:uppercase;font-weight:700;color:#ffffff;">
                      <span style="color:#fff;">●</span>&nbsp; New visitor
                    </td>
                  </tr>
                </table>
                ${spacer(22)}
                <div style="font-size:34px;font-weight:700;letter-spacing:-0.02em;line-height:1.06;color:${C.navy};">
                  Hey, someone's<br>checking you out ${ICON_EYES()}
                </div>
                ${spacer(24)}
                <table role="presentation" cellpadding="0" cellspacing="0" border="0">
                  <tr>
                    <td style="font-size:40px;font-weight:700;letter-spacing:-0.02em;line-height:1;padding-right:14px;
                      border-right:2px solid ${C.border};color:${C.navy};">${esc(visitClock)}</td>
                    <td style="padding-left:14px;font-size:13px;line-height:1.5;color:${C.muted};">
                      ${esc(visitDate)}<br><span style="color:${C.muted};">${esc(TIME_ZONE.replace('_', ' '))}</span>
                    </td>
                  </tr>
                </table>
              </td>
            </tr>

            <!-- Orange accent strip -->
            <tr>
              <td height="3" style="height:3px;line-height:3px;font-size:0;background:${C.orange};">&nbsp;</td>
            </tr>

            <!-- Location -->
            <tr>
              <td style="padding:34px 36px 8px 36px;">
                ${label('Visiting from', C.orangeInk)}
                ${spacer(10)}
                <table role="presentation" cellpadding="0" cellspacing="0" border="0">
                  <tr>
                    <td valign="middle" style="font-size:46px;line-height:1;padding-right:16px;">${flag}</td>
                    <td valign="middle">
                      <div style="font-size:30px;font-weight:700;letter-spacing:-0.02em;line-height:1.15;color:${C.navy};">${cityLine}</div>
                      ${subLocation ? `<div style="font-size:14px;color:${C.muted};margin-top:5px;">${subLocation}</div>` : ''}
                    </td>
                  </tr>
                </table>
                ${visitInfo}
              </td>
            </tr>

            <!-- Pills -->
            <tr>
              <td style="padding:26px 36px 4px 36px;">
                ${label('Using')}
                ${spacer(12)}
                <table role="presentation" cellpadding="0" cellspacing="0" border="0">
                  <tr>
                    ${pill(deviceIcon(v.device?.type), deviceName, C.tile, C.text)}
                    ${pill(iconImg('os', 16), osText, C.tile, C.text)}
                    ${pill(iconImg('globe', 16), browserText, C.tile, C.text)}
                  </tr>
                </table>
              </td>
            </tr>

            <!-- Cards -->
            <tr>
              <td style="padding:14px 30px 6px 30px;">
                <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
                  <tr>
                    ${card(iconImg('os', 24), 'Screen', esc(v.screenResolution || 'Unknown'), C.orange)}
                    ${card(iconImg('globe', 24), 'IP Address', esc(v.ip || 'Unknown'), C.navy, true)}
                  </tr>
                </table>
              </td>
            </tr>

            <!-- User agent -->
            <tr>
              <td style="padding:16px 36px 36px 36px;">
                ${label('User Agent')}
                <div style="background:${C.page};border:1px solid ${C.border};border-left:3px solid ${C.violet};border-radius:12px;margin-top:10px;
                  padding:14px 16px;font-family:${MONO};font-size:11.5px;line-height:1.7;
                  color:${C.violetSoft};word-break:break-all;">${esc(v.userAgent || 'Unknown')}</div>
              </td>
            </tr>

            <!-- Footer -->
            <tr>
              <td align="center" style="border-top:1px solid ${C.border};padding:24px 36px;">
                <div style="font-size:12px;color:${C.muted};">Sent automatically by your portfolio tracker ${ICON_HEART()}</div>
                <div style="font-size:11px;color:#545985;margin-top:6px;">
                  Generated ${esc(new Date().toLocaleString('en-US', { timeZone: TIME_ZONE }))}</div>
              </td>
            </tr>

          </table>

        </td>
      </tr>
    </table>
  </body>
</html>`;
};

const app = express();
const PORT = 3000;

app.use(cors());
app.use(bodyParser.json());

app.post('/api/track-visitor', async (req, res) => {
  console.log('Received visitor tracking request');

  let claimedIp = null;

  try {
    const visitorData = req.body;

    // Only email for an IP address we have never seen before.
    const clientIp = visitorData.ip || String(req.socket?.remoteAddress || '').replace(/^::ffff:/, '');
    if (!(await claimIp(clientIp))) {
      console.log('Known IP, skipping email:', clientIp);
      return res.status(200).json({ success: true, skipped: true, message: 'Returning visitor - no email sent' });
    }
    claimedIp = clientIp;

    const gmailUser = process.env.GMAIL_USER;
    const gmailAppPassword = process.env.GMAIL_APP_PASSWORD;
    const recipientEmail = process.env.VISITOR_NOTIFICATION_EMAIL || gmailUser;

    if (!gmailUser || !gmailAppPassword) {
      console.error('Missing Gmail credentials');
      return res.status(500).json({ error: 'Server configuration error' });
    }

    const transporter = nodemailer.createTransport({
      service: 'gmail',
      auth: { user: gmailUser, pass: gmailAppPassword },
    });

    await transporter.verify();

    const emailSubject = `New Portfolio Visitor - ${visitorData.location?.city || 'Unknown Location'}`;
    const emailHtml = buildEmailHtml({
      ...visitorData,
      language: visitorData.language || String(req.headers['accept-language'] || '').split(',')[0],
    });

    console.log('[visitor-email] v5 - visit details');
    const info = await transporter.sendMail({
      from: gmailUser,
      to: recipientEmail,
      subject: emailSubject,
      html: emailHtml,
      attachments: ICON_ATTACHMENTS.filter((a) => emailHtml.includes(`cid:${a.cid}`)),
    });

    console.log('Email sent successfully:', info.messageId);
    return res.status(200).json({ success: true, message: 'Visitor tracked and email sent' });
  } catch (error) {
    console.error('Error tracking visitor:', error);
    if (claimedIp) await releaseIp(claimedIp);
    return res.status(500).json({ error: 'Failed to track visitor', details: error.message });
  }
});

const server = app.listen(PORT, () => {
  console.log(`API Server running on http://localhost:${PORT}`);
  console.log(`API endpoint available at http://localhost:${PORT}/api/track-visitor`);
});

server.on('error', (error) => console.error('Server error:', error));
process.on('uncaughtException', (error) => console.error('Uncaught exception:', error));
process.on('unhandledRejection', (error) => console.error('Unhandled rejection:', error));